package config

import (
	"os"
	"path/filepath"
)

const (
	Port       = 8888
	RestartCmd = "xkeen -restart > /tmp/mihomo_last_restart.log 2>&1"
	UpdateCmd  = "/opt/bin/mhstudio -update"
	LogFile    = "/tmp/mihomo_last_restart.log"
	InitScript = "/opt/etc/init.d/S95mihomo-web"
)

var (
	ConfigDir   = "/opt/etc/mihomo"
	ConfigPath  string
	ProfilesDir string
	BackupDir   string
)

func Init() {
	ConfigPath = filepath.Join(ConfigDir, "config.yaml")
	ProfilesDir = filepath.Join(ConfigDir, "profiles")
	BackupDir = filepath.Join(ConfigDir, "backup")

	os.MkdirAll(BackupDir, 0755)
	os.MkdirAll(ProfilesDir, 0755)

	// Если config.yaml существует и не симлинк — перемещаем в profiles
	if info, err := os.Lstat(ConfigPath); err == nil {
		if info.Mode()&os.ModeSymlink == 0 {
			defaultProf := filepath.Join(ProfilesDir, "default.yaml")
			os.Rename(ConfigPath, defaultProf)
			os.Symlink(defaultProf, ConfigPath)
		}
	} else {
		defProf := filepath.Join(ProfilesDir, "default.yaml")
		os.WriteFile(defProf, []byte("proxies: []\n"), 0644)
		os.Symlink(defProf, ConfigPath)
	}
}

package parser

import (
	"net/url"
	"regexp"
	"strings"
)

type ProxyResult struct {
	YAML string `json:"yaml"`
	Name string `json:"name"`
}

func ParseVLESS(link, customName string) (*ProxyResult, error) {
	if !strings.HasPrefix(link, "vless://") {
		return nil, &ParseError{Msg: "Link error"}
	}

	main := link[8:]
	name := "VLESS"

	if customName != "" {
		name = customName
	} else if idx := strings.Index(main, "#"); idx != -1 {
		decoded, _ := url.QueryUnescape(main[idx+1:])
		name = strings.TrimSpace(decoded)
		main = main[:idx]
	}

	// Убираем спецсимволы из имени
	re := regexp.MustCompile(`[\[\]\{\}\"\']`)
	name = re.ReplaceAllString(name, "")

	// Разделяем user@server:port и параметры
	queryIdx := strings.Index(main, "?")
	userSrv := main
	queryParams := url.Values{}
	if queryIdx != -1 {
		userSrv = main[:queryIdx]
		queryParams, _ = url.ParseQuery(main[queryIdx+1:])
	}

	atIdx := strings.LastIndex(userSrv, "@")
	if atIdx == -1 {
		return nil, &ParseError{Msg: "No UUID"}
	}
	uuid := userSrv[:atIdx]
	srvPort := userSrv[atIdx+1:]

	var server, port string
	if strings.Contains(srvPort, "]:") {
		// IPv6
		lastColon := strings.LastIndex(srvPort, ":")
		server = srvPort[:lastColon]
		server = strings.ReplaceAll(server, "[", "")
		server = strings.ReplaceAll(server, "]", "")
		port = srvPort[lastColon+1:]
	} else if colonIdx := strings.Index(srvPort, ":"); colonIdx != -1 {
		server = srvPort[:colonIdx]
		port = srvPort[colonIdx+1:]
	} else {
		return nil, &ParseError{Msg: "No Port"}
	}

	get := func(k string) string {
		vals := queryParams[k]
		if len(vals) > 0 {
			return vals[0]
		}
		return ""
	}

	var y []string
	y = append(y, `- name: "`+name+`"`)
	y = append(y, "  type: vless")
	y = append(y, "  server: "+server)
	y = append(y, "  port: "+port)
	y = append(y, "  uuid: "+uuid)
	y = append(y, "  udp: true")

	network := get("type")
	if network == "" {
		network = "tcp"
	}
	y = append(y, "  network: "+network)

	if flow := get("flow"); flow != "" {
		y = append(y, "  flow: "+flow)
	}

	if security := get("security"); security != "" {
		y = append(y, "  tls: true")
		if security == "reality" {
			y = append(y, "  servername: "+get("sni"))
			fp := get("fp")
			if fp == "" {
				fp = "chrome"
			}
			y = append(y, "  client-fingerprint: "+fp)
			y = append(y, "  reality-opts:")
			y = append(y, "    public-key: "+get("pbk"))
			if sid := get("sid"); sid != "" {
				y = append(y, "    short-id: "+sid)
			}
		} else {
			if sni := get("sni"); sni != "" {
				y = append(y, "  servername: "+sni)
			}
			if fp := get("fp"); fp != "" {
				y = append(y, "  client-fingerprint: "+fp)
			}
			if alpn := get("alpn"); alpn != "" {
				alpn = strings.ReplaceAll(alpn, ",", `", "`)
				y = append(y, `  alpn: ["`+alpn+`"]`)
			}
		}
	}

	if network == "ws" {
		y = append(y, "  ws-opts:")
		if path := get("path"); path != "" {
			y = append(y, "    path: "+path)
		}
		if host := get("host"); host != "" {
			y = append(y, "    headers:")
			y = append(y, "      Host: "+host)
		}
	} else if network == "grpc" {
		if serviceName := get("serviceName"); serviceName != "" {
			y = append(y, "  grpc-opts:")
			y = append(y, "    grpc-service-name: "+serviceName)
		}
	}

	return &ProxyResult{
		YAML: strings.Join(y, "\n"),
		Name: name,
	}, nil
}

type ParseError struct {
	Msg string
}

func (e *ParseError) Error() string {
	return e.Msg
}

package parser

import (
	"encoding/json"
	"strconv"
	"strings"
)

func ParseWireGuard(configText, customName string) (*ProxyResult, error) {
	conf := map[string]map[string]string{
		"interface": {},
		"peer":      {},
	}
	var section string

	for _, line := range strings.Split(configText, "\n") {
		// Убираем комментарии
		if idx := strings.IndexAny(line, "#;"); idx != -1 {
			line = line[:idx]
		}
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			sName := strings.ToLower(line[1 : len(line)-1])
			if sName == "interface" || sName == "peer" {
				section = sName
			} else {
				section = ""
			}
			continue
		}

		if section != "" && strings.Contains(line, "=") {
			parts := strings.SplitN(line, "=", 2)
			key := strings.TrimSpace(strings.ToLower(parts[0]))
			val := strings.TrimSpace(parts[1])
			conf[section][key] = val
		}
	}

	iface := conf["interface"]
	peer := conf["peer"]

	if len(iface) == 0 || len(peer) == 0 {
		return nil, &ParseError{Msg: "Invalid WireGuard config: missing Interface or Peer"}
	}

	endpoint := peer["endpoint"]
	if endpoint == "" {
		return nil, &ParseError{Msg: "No Endpoint found"}
	}

	var server, port string
	if strings.Contains(endpoint, "]:") {
		parts := strings.SplitN(endpoint, "]:", 2)
		server = parts[0][1:] // убираем [
		port = parts[1]
	} else if idx := strings.LastIndex(endpoint, ":"); idx != -1 {
		server = endpoint[:idx]
		port = endpoint[idx+1:]
	} else {
		return nil, &ParseError{Msg: "Invalid Endpoint format"}
	}

	name := "WireGuard"
	if customName != "" {
		name = customName
	} else {
		lines := strings.Split(configText, "\n")
		for _, l := range lines {
			l = strings.TrimSpace(l)
			if strings.HasPrefix(l, "#") && len(l) > 2 {
				name = strings.TrimSpace(l[1:])
				break
			}
		}
		if name == "WireGuard" {
			name = "WG_" + server
		}
	}

	addressRaw := iface["address"]
	if addressRaw == "" {
		return nil, &ParseError{Msg: "No Address found"}
	}

	ips := strings.Split(addressRaw, ",")
	var ipV4, ipV6 string
	for _, ip := range ips {
		cleanIP := strings.TrimSpace(strings.Split(ip, "/")[0])
		if strings.Contains(cleanIP, ":") {
			if ipV6 == "" {
				ipV6 = cleanIP
			}
		} else {
			if ipV4 == "" {
				ipV4 = cleanIP
			}
		}
	}

	if ipV4 == "" && ipV6 == "" {
		return nil, &ParseError{Msg: "No valid IP address found"}
	}

	var y []string
	y = append(y, `- name: "`+name+`"`)
	y = append(y, "  type: wireguard")
	y = append(y, "  server: "+server)
	y = append(y, "  port: "+port)

	if ipV4 != "" {
		y = append(y, "  ip: "+ipV4)
	}
	if ipV6 != "" {
		y = append(y, "  ipv6: "+ipV6)
	}

	if pk := iface["privatekey"]; pk != "" {
		y = append(y, "  private-key: "+pk)
	}
	if pubk := peer["publickey"]; pubk != "" {
		y = append(y, "  public-key: "+pubk)
	}
	if psk := peer["presharedkey"]; psk != "" {
		y = append(y, "  pre-shared-key: "+psk)
	}

	if dnsRaw := iface["dns"]; dnsRaw != "" {
		var dnsList []string
		for _, d := range strings.Split(dnsRaw, ",") {
			dnsList = append(dnsList, strings.TrimSpace(d))
		}
		dnsJSON, _ := json.Marshal(dnsList)
		y = append(y, "  dns: "+string(dnsJSON))
	}

	if mtu := iface["mtu"]; mtu != "" {
		y = append(y, "  mtu: "+mtu)
	}

	y = append(y, "  udp: true")

	// AmneziaWG options
	stdWGKeys := map[string]bool{
		"privatekey": true, "address": true, "dns": true, "mtu": true,
		"listenport": true, "table": true, "preup": true, "postup": true,
		"predown": true, "postdown": true,
	}
	amnOpts := make(map[string]interface{})
	for k, v := range iface {
		if !stdWGKeys[k] {
			if _, err := strconv.Atoi(v); err == nil {
				val, _ := strconv.Atoi(v)
				amnOpts[k] = val
			} else if strings.HasPrefix(v, "-") {
				if _, err := strconv.Atoi(v[1:]); err == nil {
					val, _ := strconv.Atoi(v)
					amnOpts[k] = val
				} else {
					amnOpts[k] = v
				}
			} else {
				amnOpts[k] = v
			}
		}
	}

	if len(amnOpts) > 0 {
		y = append(y, "  amnezia-wg-option:")
		for k, v := range amnOpts {
			switch val := v.(type) {
			case string:
				if val == "" {
					y = append(y, "    "+k+`: ""`)
				} else {
					y = append(y, "    "+k+": "+val)
				}
			default:
				y = append(y, "    "+k+": "+strconv.Itoa(val.(int)))
			}
		}
	}

	if allowed := peer["allowedips"]; allowed != "" {
		var alList []string
		for _, x := range strings.Split(allowed, ",") {
			alList = append(alList, strings.TrimSpace(x))
		}
		alJSON, _ := json.Marshal(alList)
		y = append(y, "  allowed-ips: "+string(alJSON))
	}

	if ka := peer["persistentkeepalive"]; ka != "" {
		y = append(y, "  persistent-keepalive: "+ka)
	}

	return &ProxyResult{
		YAML: strings.Join(y, "\n"),
		Name: name,
	}, nil
}

package proxy

import (
	"fmt"
	"regexp"
	"strings"
)

// InsertProxyLogic вставляет прокси в секцию proxies и добавляет в выбранные группы
func InsertProxyLogic(content, proxyName, proxyYAML string, targetGroups []string) string {
	lines := strings.Split(content, "\n")
	newLines := make([]string, 0, len(lines)+20)

	getIndent := func(s string) int {
		return len(s) - len(strings.TrimLeft(s, " \t"))
	}

	targetSet := make(map[string]bool)
	for _, g := range targetGroups {
		targetSet[g] = true
	}

	inGroupSection := false
	var currentGroupName string
	inProxiesList := false
	proxiesListIndent := -1
	insertedInGroup := make(map[string]bool)

	// Сначала вставляем блок прокси в секцию proxies
	inProxies := false
	proxyInserted := false
	proxyLines := strings.Split(proxyYAML, "\n")

	for i, line := range lines {
		stripped := strings.TrimSpace(line)
		indent := getIndent(line)
		isNewGroup := strings.HasPrefix(stripped, "- name:")

		// Вставка в proxies
		if !proxyInserted && strings.HasPrefix(stripped, "proxies:") {
			newLines = append(newLines, line)
			for _, pl := range proxyLines {
				newLines = append(newLines, "  "+pl)
			}
			proxyInserted = true
			continue
		}

		if isNewGroup {
			if inProxiesList && targetSet[currentGroupName] && !insertedInGroup[currentGroupName] {
				prefix := strings.Repeat(" ", proxiesListIndent+2)
				newLines = append(newLines, prefix+`- "`+proxyName+`"`)
				insertedInGroup[currentGroupName] = true
			}
			inProxiesList = false
		}

		if stripped == "proxy-groups:" {
			inGroupSection = true
		} else if inGroupSection && indent == 0 && stripped != "" && !strings.HasPrefix(stripped, "#") {
			inGroupSection = false
			inProxiesList = false
			currentGroupName = ""
		}

		if inGroupSection {
			if isNewGroup {
				rawName := strings.SplitN(stripped, ":", 2)[1]
				rawName = strings.TrimSpace(rawName)
				rawName = strings.Trim(rawName, "'\"")
				currentGroupName = rawName
			}

			if targetSet[currentGroupName] && strings.HasPrefix(stripped, "proxies:") {
				// Inline list ["A", "B"]
				if strings.Contains(line, "[") && strings.HasSuffix(strings.TrimSpace(line), "]") {
					start := strings.Index(line, "[")
					end := strings.LastIndex(line, "]")
					if start != -1 && end != -1 {
						inner := line[start+1 : end]
						if !strings.Contains(inner, `"`+proxyName+`"`) && !strings.Contains(inner, `'`+proxyName+`'`) {
							sep := ", "
							if strings.TrimSpace(inner) == "" {
								sep = ""
							}
							newContent := inner + sep + `"` + proxyName + `"`
							newLine := line[:start+1] + newContent + line[end:]
							newLines = append(newLines, newLine)
							insertedInGroup[currentGroupName] = true
							continue
						} else {
							newLines = append(newLines, line)
							insertedInGroup[currentGroupName] = true
							continue
						}
					}
				}

				inProxiesList = true
				proxiesListIndent = indent
				newLines = append(newLines, line)
				continue
			}

			if inProxiesList {
				if stripped == "" || strings.HasPrefix(stripped, "#") {
					newLines = append(newLines, line)
					continue
				}
				if (strings.Contains(stripped, "DIRECT") || strings.Contains(stripped, "REJECT")) && !insertedInGroup[currentGroupName] {
					prefix := strings.Repeat(" ", indent)
					newLines = append(newLines, prefix+`- "`+proxyName+`"`)
					insertedInGroup[currentGroupName] = true
				}

				if indent <= proxiesListIndent {
					if !insertedInGroup[currentGroupName] {
						prefix := strings.Repeat(" ", proxiesListIndent+2)
						newLines = append(newLines, prefix+`- "`+proxyName+`"`)
						insertedInGroup[currentGroupName] = true
					}
					inProxiesList = false
				}
			}
		}

		newLines = append(newLines, line)

		// Для последней строки
		if i == len(lines)-1 && inProxiesList && targetSet[currentGroupName] && !insertedInGroup[currentGroupName] {
			prefix := strings.Repeat(" ", proxiesListIndent+2)
			newLines = append(newLines, prefix+`- "`+proxyName+`"`)
		}
	}

	// Если proxies не найдена — добавляем в конец
	if !proxyInserted {
		newLines = append(newLines, "proxies:")
		for _, pl := range proxyLines {
			newLines = append(newLines, "  "+pl)
		}
	}

	return strings.Join(newLines, "\n")
}

// ReplaceProxyBlock заменяет блок прокси с targetName на новый YAML
func ReplaceProxyBlock(content, targetName, newYAML string) string {
	lines := strings.Split(content, "\n")
	newContentLines := make([]string, 0, len(lines))

	inProxies := false
	replaced := false
	namePattern := regexp.MustCompile(`^\s*-\s+name:\s*(["'])?` + regexp.QuoteMeta(targetName) + `\1?\s*$`)

	newYAMLLines := strings.Split(newYAML, "\n")
	// Заменяем имя в первой строке нового YAML
	if len(newYAMLLines) > 0 && strings.Contains(newYAMLLines[0], "name:") {
		newYAMLLines[0] = regexp.MustCompile(`name:\s*"[^"]*"`).ReplaceAllString(newYAMLLines[0], `name: "`+targetName+`"`)
	}

	i := 0
	for i < len(lines) {
		line := lines[i]
		stripped := strings.TrimSpace(line)

		if strings.HasPrefix(stripped, "proxies:") {
			inProxies = true
			newContentLines = append(newContentLines, line)
			i++
			continue
		}

		if inProxies && line != "" && !strings.HasPrefix(line, " ") && !strings.HasPrefix(line, "\t") && !strings.HasPrefix(stripped, "#") {
			inProxies = false
		}

		if inProxies && !replaced && namePattern.MatchString(stripped) {
			indentLen := len(line) - len(strings.TrimLeft(line, " \t"))
			for _, nLine := range newYAMLLines {
				newContentLines = append(newContentLines, strings.Repeat(" ", indentLen)+nLine)
			}
			replaced = true

			i++
			for i < len(lines) {
				nextLine := lines[i]
				nextStripped := strings.TrimSpace(nextLine)
				nextIndent := len(nextLine) - len(strings.TrimLeft(nextLine, " \t"))
				if nextStripped == "" {
					i++
					continue
				}
				if nextIndent < indentLen {
					break
				}
				if nextIndent == indentLen && strings.HasPrefix(nextStripped, "-") {
					break
				}
				i++
			}
			continue
		}

		newContentLines = append(newContentLines, line)
		i++
	}

	return strings.Join(newContentLines, "\n")
}

// RenameProxy переименовывает прокси во всех местах конфига
func RenameProxy(content, oldName, newName string) string {
	escapedOld := regexp.QuoteMeta(oldName)

	// 1. Замена в определении прокси
	patternDef := `(name\s*:\s*)(["']?)` + escapedOld + `\2`
	content = regexp.MustCompile(patternDef).ReplaceAllString(content, `${1}"`+newName+`"`)

	// 2. Замена в списках proxy-groups
	patternList := `(-\s+)(["']?)` + escapedOld + `\2`
	content = regexp.MustCompile(patternList).ReplaceAllString(content, `${1}"`+newName+`"`)

	// 3. Замена в inline lists
	patternInline := `([\[,]\s*)(["']?)` + escapedOld + `\2(\s*[\],])`
	content = regexp.MustCompile(patternInline).ReplaceAllString(content, fmt.Sprintf(`${1}${2}%s${2}${3}`, newName))

	return content
}

// DeleteProxy удаляет прокси из конфига
func DeleteProxy(content, proxyName string) string {
	lines := strings.Split(content, "\n")
	nls := make([]string, 0, len(lines))
	inP := false
	delB := false
	bInd := -1

	escapedName := regexp.QuoteMeta(proxyName)
	namePattern := regexp.MustCompile(`^\s*-\s+name:\s*["']?` + escapedName + `["']?\s*$`)
	listPattern := regexp.MustCompile(`^\s+-\s+(?:"` + escapedName + `"|'` + escapedName + `'|` + escapedName + `)\s*$`)

	for _, l := range lines {
		stripped := strings.TrimSpace(l)

		if strings.HasPrefix(stripped, "proxies:") && !strings.Contains(stripped, "[") {
			inP = true
			nls = append(nls, l)
			continue
		}
		if inP && l != "" && !strings.HasPrefix(l, " ") && !strings.HasPrefix(l, "\t") && !strings.HasPrefix(stripped, "#") {
			inP = false
			delB = false
		}

		if inP {
			if namePattern.MatchString(l) {
				delB = true
				bInd = len(l) - len(strings.TrimLeft(l, " \t"))
				continue
			} else if delB {
				ci := len(l) - len(strings.TrimLeft(l, " \t"))
				if stripped == "" || ci > bInd {
					continue
				} else {
					delB = false
				}
			}
		}

		if delB {
			continue
		}

		// Inline list
		if strings.Contains(l, "[") && strings.Contains(l, "]") && strings.Contains(l, "proxies:") {
			// Не трогаем, обрабатываем отдельно
		}

		// Удаление из списков групп
		if listPattern.MatchString(l) {
			continue
		}

		// Удаление из inline списков
		if strings.Contains(l, "[") && strings.Contains(l, "]") {
			start := strings.Index(l, "[")
			end := strings.LastIndex(l, "]")
			if start != -1 && end != -1 {
				pre := l[:start+1]
				suf := l[end:]
				mid := l[start+1 : end]
				parts := strings.Split(mid, ",")
				var res []string
				changed := false
				for _, p := range parts {
					clean := strings.TrimSpace(strings.Trim(p, "\"'"))
					if clean == proxyName {
						changed = true
					} else {
						res = append(res, p)
					}
				}
				if changed {
					nls = append(nls, pre+strings.Join(res, ",")+suf)
					continue
				}
			}
		}

		nls = append(nls, l)
	}

	return strings.Join(nls, "\n")
}

// GetProxiesList извлекает список имён прокси из конфига
func GetProxiesList(content string) []string {
	lines := strings.Split(content, "\n")
	var prs []string
	inP := false
	nameRe := regexp.MustCompile(`^\s+-\s+name:\s+(.*)`)

	for _, l := range lines {
		stripped := strings.TrimSpace(l)
		if strings.HasPrefix(stripped, "proxies:") {
			inP = true
			continue
		}
		if inP && l != "" && !strings.HasPrefix(l, " ") && !strings.HasPrefix(l, "\t") && !strings.HasPrefix(stripped, "#") {
			inP = false
		}
		if inP {
			if m := nameRe.FindStringSubmatch(l); m != nil {
				name := strings.TrimSpace(m[1])
				name = strings.Trim(name, "\"'")
				prs = append(prs, name)
			}
		}
	}
	return prs
}

// GetGroupsList извлекает список групп из конфига
func GetGroupsList(content string) []string {
	lines := strings.Split(content, "\n")
	var grps []string
	inG := false
	nameRe := regexp.MustCompile(`^\s+-\s+name:\s+(.*)`)

	for _, l := range lines {
		stripped := strings.TrimSpace(l)
		if strings.HasPrefix(stripped, "proxy-groups:") {
			inG = true
			continue
		}
		if inG && l != "" && !strings.HasPrefix(l, " ") && !strings.HasPrefix(l, "\t") && !strings.HasPrefix(stripped, "#") {
			inG = false
		}
		if inG {
			if m := nameRe.FindStringSubmatch(l); m != nil {
				name := strings.TrimSpace(m[1])
				name = strings.Trim(name, "\"'")
				grps = append(grps, name)
			}
		}
	}
	return grps
}

package profile

import (
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/l-ptrol/mhstudio-go/internal/config"
)

type ProfileInfo struct {
	Name    string
	Path    string
	Content string
}

// ListProfiles возвращает список всех профилей
func ListProfiles() ([]ProfileInfo, error) {
	files, err := filepath.Glob(filepath.Join(config.ProfilesDir, "*.yaml"))
	if err != nil {
		return nil, err
	}
	sort.Strings(files)

	var profiles []ProfileInfo
	for _, f := range files {
		name := strings.TrimSuffix(filepath.Base(f), ".yaml")
		profiles = append(profiles, ProfileInfo{Name: name, Path: f})
	}
	return profiles, nil
}

// GetCurrentProfile возвращает имя текущего активного профиля
func GetCurrentProfile() string {
	real, err := filepath.EvalSymlinks(config.ConfigPath)
	if err != nil {
		return ""
	}
	return strings.TrimSuffix(filepath.Base(real), ".yaml")
}

// SwitchProfile переключает активный профиль
func SwitchProfile(name string) error {
	target := filepath.Join(config.ProfilesDir, name+".yaml")
	if _, err := os.Stat(target); err != nil {
		return &OpError{Msg: "Profile not found"}
	}

	// Удаляем текущий симлинк
	os.Remove(config.ConfigPath)
	return os.Symlink(target, config.ConfigPath)
}

// AddProfile создаёт новый профиль
func AddProfile(name, content string) error {
	target := filepath.Join(config.ProfilesDir, name+".yaml")
	if _, err := os.Stat(target); err == nil {
		return &OpError{Msg: "Профиль с таким именем уже существует"}
	}
	return os.WriteFile(target, []byte(content), 0644)
}

// DeleteProfile удаляет профиль
func DeleteProfile(name string) error {
	target := filepath.Join(config.ProfilesDir, name+".yaml")

	// Нельзя удалить активный профиль
	realCurr, _ := filepath.EvalSymlinks(config.ConfigPath)
	realTarget, _ := filepath.EvalSymlinks(target)
	if realTarget == realCurr {
		return &OpError{Msg: "Нельзя удалить активный профиль. Сначала переключитесь на другой."}
	}

	return os.Remove(target)
}

// GetProfileContent возвращает содержимое профиля
func GetProfileContent(name string) (string, error) {
	target := filepath.Join(config.ProfilesDir, name+".yaml")
	data, err := os.ReadFile(target)
	if err != nil {
		return "", &OpError{Msg: "Profile not found"}
	}
	return string(data), nil
}

type OpError struct {
	Msg string
}

func (e *OpError) Error() string {
	return e.Msg
}

package backup

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/l-ptrol/mhstudio-go/internal/config"
)

type BackupInfo struct {
	Name    string
	Path    string
	ModTime time.Time
	Content string
}

// ListBackups возвращает все бэкапы, отсортированные по дате (новые первыми)
func ListBackups() ([]BackupInfo, error) {
	files, err := filepath.Glob(filepath.Join(config.BackupDir, "*.yaml"))
	if err != nil {
		return nil, err
	}

	// Сортируем по времени модификации (новые первыми)
	sort.Slice(files, func(i, j int) bool {
		fi, _ := os.Stat(files[i])
		fj, _ := os.Stat(files[j])
		return fi.ModTime().After(fj.ModTime())
	})

	var backups []BackupInfo
	for _, f := range files {
		fi, _ := os.Stat(f)
		backups = append(backups, BackupInfo{
			Name:    filepath.Base(f),
			Path:    f,
			ModTime: fi.ModTime(),
		})
	}
	return backups, nil
}

// CreateBackup создаёт бэкап текущего конфига
func CreateBackup() error {
	realPath, err := filepath.EvalSymlinks(config.ConfigPath)
	if err != nil {
		return err
	}
	profName := strings.TrimSuffix(filepath.Base(realPath), ".yaml")
	ts := time.Now().Format("20060102_150405")
	backupPath := filepath.Join(config.BackupDir, profName+"_"+ts+".yaml")

	data, err := os.ReadFile(config.ConfigPath)
	if err != nil {
		return err
	}
	return os.WriteFile(backupPath, data, 0644)
}

// RestoreBackup восстанавливает конфиг из бэкапа
func RestoreBackup(filename string) error {
	path := filepath.Join(config.BackupDir, filepath.Base(filename))
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return os.WriteFile(config.ConfigPath, data, 0644)
}

// ViewBackup возвращает содержимое бэкапа
func ViewBackup(filename string) (string, error) {
	path := filepath.Join(config.BackupDir, filepath.Base(filename))
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// DeleteBackup удаляет бэкап
func DeleteBackup(filename string) error {
	path := filepath.Join(config.BackupDir, filepath.Base(filename))
	return os.Remove(path)
}

// CleanBackups оставляет только N последних бэкапов
func CleanBackups(limit int) error {
	backups, err := ListBackups()
	if err != nil {
		return err
	}
	if len(backups) > limit {
		for _, b := range backups[limit:] {
			os.Remove(b.Path)
		}
	}
	return nil
}

